<main class="admin-shell"><?= view('partials/admin_sidebar',['active'=>'events']) ?><section class="admin-content"><div class="admin-topbar"><div><span class="eyebrow accent">PROGRAMME BUILDER</span><h1 data-testid="events-page-title">Events</h1></div><a class="button button-yellow" href="<?= base_url('admin/events/new') ?>" data-testid="events-new-button">New event <span>↗</span></a></div><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">COMPLETE LINEUP</span><h2 data-testid="admin-event-count"><?= count($events) ?> events</h2></div><a class="text-link" href="<?= base_url('admin/categories') ?>">Manage categories ↗</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Event</th><th>Category</th><th>Fee</th><th>Status</th><th>Capacity</th><th>Actions</th></tr></thead><tbody><?php foreach($events as $event): ?><tr data-testid="admin-event-row"><td><strong><?= esc($event['name']) ?></strong><span class="table-sub">/<?= esc($event['slug']) ?></span></td><td><?= esc($event['category_name']) ?></td><td><?= $event['fee']>0?esc(money($event['fee'])):'FREE' ?></td><td><span class="<?= status_class($event['status']) ?>"><?= esc(strtoupper(str_replace('_',' ',$event['status']))) ?></span></td><td><?= esc($event['capacity']?:'∞') ?></td><td><div class="row-actions"><a class="table-action" href="<?= base_url('admin/events/'.$event['id'].'/edit') ?>" data-testid="event-edit-<?= esc($event['id']) ?>">Edit</a><a class="table-action" href="<?= base_url('events/'.$event['slug']) ?>" target="_blank" rel="noopener">View</a><form method="post" action="<?= base_url('admin/events/'.$event['id'].'/delete') ?>"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><button class="table-action danger-action" type="submit" data-confirm="Delete or archive this event?" data-testid="event-delete-<?= esc($event['id']) ?>">Delete</button></form></div></td></tr><?php endforeach ?></tbody></table></div></div></section></main>